begin;
do $$
declare token text;versions jsonb;items jsonb;plan jsonb;
begin
 assert not exists(select 1 from public.periods where month in('2000-01','2000-02','2000-03','2000-04')),'Synthetic periods exist';
 insert into public.periods(month,status,commission_status) values('2000-01','closed','closed'),('2000-02','open','open'),('2000-03','open','open'),('2000-04','closed','closed');
 insert into public.employees(id,registration,active) values('test-salary-events','TEST-SALARY-EVENTS',1);
 insert into public.versions(employee,month,data) values('test-salary-events','2000-01','{"D":"1999-01-01","K":"1000.00","C":"Pessoa fictícia"}');
 insert into public.records(month,employee,data,revision) values('2000-01','test-salary-events','{"historical":"unchanged"}',77),('2000-02','test-salary-events','{"D":"1999-01-01","K":"1000.00","CK":"5.00","U":"0.00"}',1),('2000-03','test-salary-events','{"D":"1999-01-01","K":"1000.00","CK":"5.00"}',1),('2000-04','test-salary-events','{"future":"locked"}',88);
 plan:='{"id":"test-event-plan-db-0001","employee":"test-salary-events","event":"CK","amount":1000,"count":2,"start":"2000-02","end":"2000-03"}';
 assert public.register_finance_event_plan('2000-02','test-salary-event-term',plan),'Event registration failed';
 assert public.register_finance_event_plan('2000-02','test-salary-event-term',plan),'Duplicate retry failed';
 assert (select revision=2 and data::jsonb->>'CK'='15.00' and data::jsonb->>'_eventAutoCK'='1000' from public.records where month='2000-02'),'Event double applied or manual value lost';
 assert not public.register_finance_event_plan('2000-02','test-salary-event-term',plan||'{"id":"test-event-plan-db-0002","count":3,"end":"2000-04"}'),'Closed period event accepted';
 token:=public.finance_calculation_snapshot('2000-02')->>'token';
 versions:='[{"employee":"test-salary-events","data":"{\"D\":\"1999-01-01\",\"K\":\"1100.00\"}"}]';
 items:='[{"employee":"test-salary-events","revision":99,"data":"{\"D\":\"1999-01-01\",\"K\":\"1100.00\",\"U\":\"0.00\"}"}]';
 assert not public.save_finance_salary('2000-02','test-salary-event-term',token,'salary_rows_apply',true,versions,items),'Stale salary accepted';
 assert not exists(select 1 from public.versions where employee='test-salary-events' and month='2000-02'),'Partial salary version saved';
 items:=jsonb_set(items,'{0,revision}','2');
 assert public.save_finance_salary('2000-02','test-salary-event-term',token,'salary_rows_apply',true,versions,items),'Salary failed';
 assert (select data::jsonb->>'K'='1100.00' and revision=3 from public.records where month='2000-02'),'Salary record failed';
 token:=public.finance_calculation_snapshot('2000-02')->>'token';
 assert public.save_finance_salary('2000-02','test-salary-event-term',token,'salary_adjust',false,versions,'[]'),'Collective base-only salary failed';
 assert (select revision=3 from public.records where month='2000-02'),'Base-only changed monthly record';
 token:=public.finance_termination_snapshot('2000-02','test-salary-events')->>'token';
 assert not public.save_finance_termination('2000-02','test-salary-events','test-salary-event-term',token,3,'{"G":"Rescisão"}','{"G":"Rescisão"}','2000-02-15'),'Future locked month ignored';
 assert (select active=1 from public.employees where id='test-salary-events'),'Partial termination changed active';
 update public.periods set status='open',commission_status='open' where month='2000-04';
 assert not public.save_finance_termination('2000-02','test-salary-events','test-salary-event-term',token,3,'{"G":"Rescisão"}','{"G":"Rescisão"}','2000-02-15'),'Future status CAS ignored';
 token:=public.finance_termination_snapshot('2000-02','test-salary-events')->>'token';
 assert public.save_finance_termination('2000-02','test-salary-events','test-salary-event-term',token,3,'{"G":"Rescisão","_termination":true,"_excluded":true}','{"G":"Rescisão","terminationDate":"2000-02-15"}','2000-02-15'),'Termination failed';
 assert (select active=0 from public.employees where id='test-salary-events'),'Employee active';
 assert (select revision=4 and data::jsonb->>'_termination'='true' from public.records where month='2000-02'),'Settlement record wrong';
 assert (select bool_and(data::jsonb->>'_terminationCarry'='true' and data::jsonb->>'salaryCompetencia'='0.00') from public.records where employee='test-salary-events' and month>'2000-02'),'Future carry missing';
 assert (select revision=77 and data='{"historical":"unchanged"}' from public.records where month='2000-01'),'Historical row changed';
 assert (select data::jsonb->>'K'='1000.00' from public.versions where employee='test-salary-events' and month='2000-01'),'Historical base changed';
 assert (select count(*)=4 from public.audit where actor='test-salary-event-term'),'Audit missing';
 assert not has_function_privilege('anon','public.register_finance_event_plan(text,text,jsonb)','execute');
 assert not has_function_privilege('authenticated','public.save_finance_salary(text,text,text,text,boolean,jsonb,jsonb)','execute');
 assert not has_function_privilege('anon','public.save_finance_termination(text,text,text,text,integer,text,text,text)','execute');
end $$;
select 'PASS: event idempotence/manual amounts/closed periods; salary atomicity/revision; termination future locks/CAS/carry; prior history, audit and access restrictions' as result;
rollback;
